class Chunk:
    def __init__(self, imgdata: Image, index, attempt: int=0):
        self.image_data = imgdata
        self.index = index
        self.pixels = list()
        size = imgdata.size
        for y in range(size[1])[::max(1,(size[1])//5 - attempt*3)]:
            for x in range(size[0])[::max(1,(size[0])//5 - attempt*3)]:
                self.pixels.append(imgdata.getpixel((x, y)))
    
    def __sub__(self, other: Chunk) -> int:
        if len(self.pixels) != len(other.pixels):
            print(len(self.pixels), len(other.pixels))
            raise ValueError
        total = 0
        for i in range(len(self.pixels)):
            p1 = self.pixels[i]
            p2 = other.pixels[i]
            if p1[3] < 10:
                if p2[0] < 127 or p2[1] < 127 or p2[2] < 127:
                    total += 1000
            elif p2[3] < 10:
                if p1[0] < 127 or p1[1] < 127 or p1[2] < 127:
                    total += 1000
            else:
                total += abs(p1[0]-p2[0]) + abs(p1[1]-p2[1]) + abs(p1[2]-p2[2])
        return total

