s = requests.Session()

r = s.get(ENDPOINT)
r = s.post(ENDPOINT+"/api/setname", json={'name':USERNAME})

print(s.cookies)

attempt = 0
i = 0
while i < 30:
    r = s.get(ENDPOINT+"/api/newpuzzle")
    s_t = time.time()

    puzzledata = r.json()

    if 'error' in puzzledata:
        print(puzzledata)
        continue

    puzzle = Puzzle(puzzledata, attempt)
    print(puzzle.name)

    solution = puzzle.solve()
    
    time.sleep(max(0, 0.350-time.time()+s_t))

    r = s.post(ENDPOINT+'/api/checkanswer', json={'puzzle_id': puzzle.puzzle_id, 'answer': solution}).json()

    if 'error' in r:
        print(r)
        continue

    if r['correct'] == False:
        print(f"{puzzle.name} wrong")
        r = s.post(ENDPOINT+'/api/skipuzzle', json={'puzzle_id': puzzle.puzzle_id})
        attempt += 1

    else:
        print(f"{puzzle.name} solved")
        i += 1
        attempt = 0
    time.sleep(0.350)
